class Connection:
    def __enter__(self):
        print('Opening connection for Kakade')
        return self
    def __exit__(self, *e):
        print('Closing connection')
with Connection():
    print('Using connection')

from contextlib import contextmanager
@contextmanager
def kakade_session():
    print('Opening')
    try:
        yield 'Kakade session'
    finally:
        print('Closing')
with kakade_session() as s:
    print(s)

from time import perf_counter
class Timer:
    def __enter__(self):
        self.s = perf_counter()
        return self
    def __exit__(self, *e):
        print(f'{perf_counter()-self.s:.4f}s')
with Timer():
    sum(range(100000))
